<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deny</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Bash(rm -rf *)&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
